const first = $input.first()?.json || {};
if (first.error) {
  const msg = typeof first.error === 'string'
    ? first.error
    : (first.error.message || first.message || 'Google Sheets error');
  return [{
    json: {
      success: false,
      result: null,
      error: {
        type: 'EXTERNAL_SERVICE_ERROR',
        message: msg,
        retryable: true,
      },
    },
  }];
}

const data = $input.all().filter((item) => item.json && item.json.ruc_clpv);

function clean(value = '') {
  return String(value).replace(/<br\s*\/?>/gi, '').trim();
}

function extractSector(nomRouter = '') {
  const value = clean(nomRouter);
  if (!value) return '';
  const parts = value.split('-').map((p) => p.trim()).filter(Boolean);
  const ignored = ['MKT', 'MTD'];
  const sector = parts.find((p) => !ignored.includes(p.toUpperCase()));
  if (!sector) return '';
  return sector.toLowerCase().replace(/\s+/g, ' ').trim();
}

function extractOltName(nomOlt = '') {
  const value = clean(nomOlt).toUpperCase();
  if (!value) return '';
  if (value.startsWith('CDATA-')) return 'cData';
  if (value === 'SOLES_CDATA') return 'solesCData';
  if (value === 'SOLES_KINGTYPE') return 'solesKingtype';
  if (value === 'SANTA BARBARA') return 'santaBarbara';
  if (value === 'CALACALI') return 'calacali';
  if (value === 'PIFO') return 'pifo';
  if (value === 'POMASQUI') return 'pomasqui';
  if (value === 'BELLAVISTA') return 'bellavista';
  if (value === 'TOTORACOCHA') return 'totoracocha';
  return value.toLowerCase().replace(/\s+/g, ' ').trim();
}

function extractPon(ponOnu = '') {
  const match = String(ponOnu).match(/\/(\d+):/);
  return match ? match[1] : '';
}

function extractIp(ips = '') {
  const value = clean(ips);
  const match = value.match(/\b(?:\d{1,3}\.){3}\d{1,3}\b/);
  return match ? match[0] : '';
}

function buildContract(row) {
  const sector = extractSector(row.nom_router);
  const ip = extractIp(row.ips);
  return {
    id: row.ruc_clpv,
    name: row.nom_clpv,
    address: row.direccion,
    status: row.estado,
    ip,
    router: {
      sector,
      olt_name: extractOltName(row.nom_olt),
      pon: extractPon(row.pon_onu),
      serial: clean(row.seriales),
      ip,
    },
  };
}

let contracts;
if (data.length <= 1) {
  contracts = data.map((item) => buildContract(item.json));
} else {
  const input = $('Webhook').first().json.body?.input || {};
  const address = String(input.address || '').toLowerCase();
  const name = String(input.name || '').toLowerCase();
  const serial = input.serial;
  const filteredData = data.filter((item) => {
    const row = item.json;
    const itemName = String(row.nom_clpv || '').toLowerCase();
    const itemAddress = String(row.direccion || '').toLowerCase();
    const itemSerial = clean(row.seriales);
    const matchesName = !name || itemName.includes(name);
    const matchesAddress = !address || itemAddress.includes(address);
    const matchesSerial = !serial || String(itemSerial) === String(serial);
    return matchesName && matchesAddress && matchesSerial;
  });
  contracts = filteredData.map((item) => buildContract(item.json));
}

return [{
  json: {
    success: true,
    result: {
      found: contracts.length > 0,
      contractNumbers: contracts.length,
      contracts,
    },
    error: null,
  },
}];

const data = $('Get identity').all();

/**
 * Helpers
 */

function clean(value = "") {
	return value
		.replace(/<br\s*\/?>/gi, "")
		.trim();
}

function extractSector(nomRouter = "") {
	const value = clean(nomRouter);

	if (!value) return "";

	const parts = value
		.split("-")
		.map(p => p.trim())
		.filter(Boolean);

	const ignored = ["MKT", "MTD"];

	const sector = parts.find(p => !ignored.includes(p.toUpperCase()));

	if (!sector) return "";

	return sector
		.toLowerCase()
		.replace(/\s+/g, " ")
		.trim();
}

function extractOltName(nomOlt = "") {
	const value = clean(nomOlt).toUpperCase();

	if (!value) return "";

	if (value.startsWith("CDATA-")) return "cData";
	if (value === "SOLES_CDATA") return "solesCData";
	if (value === "SOLES_KINGTYPE") return "solesKingtype";
	if (value === "SANTA BARBARA") return "santaBarbara";
	if (value === "CALACALI") return "calacali";
	if (value === "PIFO") return "pifo";
	if (value === "POMASQUI") return "pomasqui";
	if (value === "BELLAVISTA") return "bellavista";
	if (value === "TOTORACOCHA") return "totoracocha";

	return value
		.toLowerCase()
		.replace(/\s+/g, " ")
		.trim();
}

function extractPon(ponOnu = "") {
	const match = ponOnu.match(/\/(\d+):/);
	return match ? match[1] : "";
}

function buildContract(row) {
	const sector = extractSector(row.nom_router);

	return {
		id: row.ruc_clpv ? row.ruc_clpv.toString() : "",
		name: row.nom_clpv,
		address: row.direccion,
		status: row.estado,

		router: {
			sector,
			olt_name: extractOltName(row.nom_olt, sector),
			pon: extractPon(row.pon_onu),
			serial: row.seriales
		}
	};
}

// Safely obtain input payload regardless of trigger source (Webhook vs Subworkflow)
let inputParams = {};
try {
	if ($('Webhook').isExecuted) {
		inputParams = $('Webhook').first()?.json?.body?.input || {};
	} else if ($('When Executed by Another Workflow').isExecuted) {
		inputParams = $('When Executed by Another Workflow').first()?.json || {};
	}
} catch (e) {
	inputParams = {};
}

// Filter valid rows (ignoring empty output when Google Sheets returns no match)
const validRows = data.filter(item => item.json && item.json.ruc_clpv);

if (validRows.length === 0) {
	return [
		{
			json: {
				success: true,
				result: {
					found: false,
					contractNumbers: 0,
					contracts: []
				}
			}
		}
	];
}

/**
 * Solo existe un contrato
 */
if (validRows.length === 1) {
	return [
		{
			json: {
				success: true,
				result: {
					found: true,
					contractNumbers: 1,
					contracts: [
						buildContract(validRows[0].json)
					]
				}
			}
		}
	];
}

/**
 * Filtrado opcional cuando existen varios contratos
 */
const address = (inputParams.address || "").toLowerCase();
const name = (inputParams.name || "").toLowerCase();
const serial = inputParams.serial;

let filteredData = validRows;
if (address || name || serial) {
	filteredData = validRows.filter(item => {
		const row = item.json;

		const itemName = (row.nom_clpv || "").toLowerCase();
		const itemAddress = (row.direccion || "").toLowerCase();
		const itemSerial = row.seriales;

		const matchesName = !name || itemName.includes(name);
		const matchesAddress = !address || itemAddress.includes(address);
		const matchesSerial = !serial || (itemSerial && itemSerial.toString() == serial.toString());

		return matchesName && matchesAddress && matchesSerial;
	});
}

const contracts = filteredData.map(item => buildContract(item.json));

return [
	{
		json: {
			success: true,
			result: {
				found: contracts.length > 0,
				contractNumbers: contracts.length,
				contracts
			}
		}
	}
];
